<template><div class="page"><div class="page-header"><div><el-button link @click="router.back()"><ArrowLeft/>返回课程列表</el-button><h1 class="page-title">{{course.name||'课程详情'}}</h1><p class="page-description">{{course.description||'暂无课程简介'}}</p></div><el-button type="primary" @click="router.push(`/knowledge/upload?course=${course.id}`)"><Upload/>上传资料</el-button></div><PageState :loading="loading" :error="error" @retry="load"><div class="metric-grid course-metrics"><div class="card metric-card" v-for="(v,k) in course.statistics" :key="k"><div><div class="metric-label">{{labels[k]}}</div><div class="metric-value">{{v}}</div></div></div></div><div class="card card-body detail"><el-descriptions :column="2" border><el-descriptions-item label="课程编号">{{course.code||'-'}}</el-descriptions-item><el-descriptions-item label="状态"><StatusTag :value="course.status"/></el-descriptions-item><el-descriptions-item label="适用年级">{{course.grade||'-'}}</el-descriptions-item><el-descriptions-item label="适用专业">{{course.major||'-'}}</el-descriptions-item><el-descriptions-item label="创建时间">{{new Date(course.created_at).toLocaleString()}}</el-descriptions-item><el-descriptions-item label="更新时间">{{new Date(course.updated_at).toLocaleString()}}</el-descriptions-item><el-descriptions-item label="备注" :span="2">{{course.remark||'-'}}</el-descriptions-item></el-descriptions></div></PageState></div></template><script setup>import{ref,onMounted}from'vue';import{useRoute,useRouter}from'vue-router';import{coursesApi}from'../../api';import PageState from'../../components/PageState.vue';import StatusTag from'../../components/StatusTag.vue';const route=useRoute(),router=useRouter(),course=ref({statistics:{}}),loading=ref(true),error=ref(''),labels={files:'知识库文件',chapters:'章节',knowledge_points:'知识点',questions:'题目',papers:'试卷'};const load=async()=>{loading.value=true;try{course.value=await coursesApi.get(route.params.id)}catch(e){error.value=e.message}finally{loading.value=false}};onMounted(load)</script><style scoped>.course-metrics{grid-template-columns:repeat(5,1fr)}.detail{margin-top:18px}</style>
